    """Return the nth Fibonacci number, where fib(0) = 0 and fib(1) = 1.

    Uses an iterative approach with O(n) time and O(1) space.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b
